function runOra14(testJS, helpersJS, sources) {
  let assertions = 0;
  const reads = [];
  const messages = [];
  function strictEqual(a, b) {
    if (Object.is(a, b)) return true;
    if (a === null || b === null || typeof a !== 'object' || typeof b !== 'object') return false;
    if (Array.isArray(a) !== Array.isArray(b)) return false;
    if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false;
    const ka = Reflect.ownKeys(a), kb = Reflect.ownKeys(b);
    if (ka.length !== kb.length) return false;
    return ka.every(k => Object.hasOwn(b, k) && strictEqual(a[k], b[k]));
  }
  function requireAssertion(ok, message, actual, expected) {
    assertions += 1;
    if (!ok) {
      const error = new Error(message || `Assertion ${assertions} failed`);
      error.actual = actual;
      error.expected = expected;
      throw error;
    }
  }
  const assert = {
    ok: (value, message) => requireAssertion(Boolean(value), message, value, true),
    equal: (a, b, message) => requireAssertion(Object.is(a, b), message, a, b),
    deepEqual: (a, b, message) => requireAssertion(strictEqual(a, b), message, a, b),
  };
  const pathResolve = (...parts) => {
    let output = [];
    for (const part of parts) {
      if (part.startsWith('/')) output = [];
      for (const token of part.split('/')) {
        if (!token || token === '.') continue;
        if (token === '..') output.pop(); else output.push(token);
      }
    }
    return '/' + output.join('/');
  };
  const readFileSync = (absolute, encoding) => {
    if (encoding !== 'utf8' || !absolute.startsWith('/source/')) throw new Error('Unexpected file read contract');
    const path = absolute.slice('/source/'.length);
    if (!Object.hasOwn(sources, path)) throw new Error('Missing exact dependency: ' + path);
    reads.push(path);
    return sources[path];
  };
  const dirname = value => value.slice(0, value.lastIndexOf('/'));
  const fileURLToPath = value => {
    if (value !== 'file:///source/frontend/src/components/ora/ora14.test.ts') throw new Error('Unexpected module URL');
    return value.slice('file://'.length);
  };
  class SearchParamsAdapter {
    constructor() { this.entries = new Map(); }
    set(key, value) { this.entries.set(String(key), String(value)); }
    toString() {
      const encode = value => encodeURIComponent(value).replace(/[!'()~]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
      return Array.from(this.entries, ([key, value]) => encode(key) + '=' + encode(value)).join('&');
    }
  }
  try {
    const helpers = new Function('URLSearchParams', helpersJS +
      '\nreturn {contextFromPlanBundle,oraErrorSentence,buildOraConversationHref,oraEntryPointFrom};')(SearchParamsAdapter);
    new Function('assert', 'readFileSync', 'fileURLToPath', 'dirname', 'resolve',
      'contextFromPlanBundle', 'oraErrorSentence', 'buildOraConversationHref', 'oraEntryPointFrom', 'console', testJS)(
      assert, readFileSync, fileURLToPath, dirname, pathResolve,
      helpers.contextFromPlanBundle, helpers.oraErrorSentence, helpers.buildOraConversationHref,
      helpers.oraEntryPointFrom, {log: value => messages.push(String(value))}
    );
    return {completed: true, assertions, reads, messages};
  } catch (error) {
    return {completed: false, assertions, reads, messages, error: {
      message: String(error.message), actual: error.actual, expected: error.expected,
      stack: String(error.stack).split('\n').slice(0, 8),
    }};
  }
}

