/**
 * Pure shaping for the ORA conversation surface.
 *
 * Deliberately free of imports: this is the part that decides what a person
 * reads, and it should be checkable without a network, a theme or a bundler.
 */


/**
 * The header for a conversation opened on a document.
 *
 * The title is read from the document itself rather than carried in the URL:
 * a filename can say a great deal about a person, and the route is not the
 * place for it. Nothing is invented — with no readable title there is no
 * header, and the conversation simply opens without one.
 */
function contextFromDocument(doc) {
  const title = String(
    doc?.display_title || doc?.user_title || doc?.original_filename || doc?.filename || '',
  ).trim();
  if (!title) return null;
  return { goal: title, step: null, material: null };
}

/**
 * What ORA already has in hand, read off the plan bundle that already exists.
 *
 * Returns null rather than a placeholder: a header that says nothing real is
 * worse than no header, because it teaches the user to ignore the space where
 * the real thing appears.
 */
function contextFromPlanBundle(
  bundle,
  { objectId, planItemId },
) {
  const goal = String(bundle?.plan?.summary || '').trim();
  if (!goal) return null;

  const objects = Array.isArray(bundle?.objects) ? bundle.objects : [];
  const material = objectId
    ? String(objects.find((o) => o?.id === objectId)?.title || '').trim() || null
    : null;

  const items = Array.isArray(bundle?.plan?.items) ? bundle.plan.items : [];
  const named = planItemId ? items.find((i) => i?.id === planItemId) : null;
  // Fall back to whatever the plan itself considers next — the same step the
  // Workspace shows under ADESSO, so the two surfaces agree.
  const step = String(named?.title || bundle?.next_item?.title || '').trim() || null;

  return { goal, step, material };
}

/**
 * The conversation's own words for a failure, or null when it has no opinion.
 *
 * The app-wide translator serves setup screens and dev surfaces, where "check
 * EXPO_PUBLIC_BACKEND_URL" is genuinely the right advice. In a conversation it
 * is not: the user cannot start a backend, and being told to is worse than
 * being told nothing. Connectivity and server failures get one plain sentence
 * here; anything else falls through to the shared translation.
 */
function oraErrorSentence(err) {
  const code = String(err?.code || '').toLowerCase();
  const raw = String(err?.message || '').toLowerCase();
  const offline =
    code === 'network_unreachable' ||
    code === 'backend_url_missing' ||
    Boolean(err?.network) ||
    /failed to fetch|network request failed|load failed|networkerror|offline/.test(raw);
  if (offline) return 'Non riesco a raggiungere ORA in questo momento. Riprova fra poco.';
  if (Number(err?.status || 0) >= 500) return 'ORA ha avuto un problema nel rispondere. Riprova fra poco.';
  return null;
}

const ENTRY_POINTS = [
  'home',
  'ora',
  'goal_workspace',
  'continue',
  'focus',
  'object',
  'vita',
  'document',
  'question',
  'opportunity',
  'notification',
];

/** Read an entry point off a URL, falling back to a plain ORA opening. */
function oraEntryPointFrom(raw) {
  const v = Array.isArray(raw) ? raw[0] : raw;
  return ENTRY_POINTS.includes(String(v || ''))
    ? (String(v))
    : 'ora';
}

const OPAQUE_ID = /^[A-Za-z0-9_-]{4,80}$/;

function opaque(id) {
  if (!id) return undefined;
  const s = String(id).trim();
  return OPAQUE_ID.test(s) ? s : undefined;
}

/** Build production ORA conversation href (never /ora-ai). */
function buildOraConversationHref(p) {
  const sessionId = opaque(p.sessionId);
  const base = sessionId ? `/ora/${sessionId}` : '/ora';
  const q = new URLSearchParams();
  if (sessionId && p.opening) q.set('opening', '1');
  const planId = opaque(p.planId);
  const objectId = opaque(p.objectId);
  const planItemId = opaque(p.planItemId);
  const documentId = opaque(p.documentId);
  const questionId = opaque(p.questionId);
  const opportunityId = opaque(p.opportunityId);
  const entry = p.entryPoint;
  if (planId) q.set('planId', planId);
  if (objectId) q.set('objectId', objectId);
  if (planItemId) q.set('planItemId', planItemId);
  if (documentId) q.set('documentId', documentId);
  if (questionId) q.set('questionId', questionId);
  if (opportunityId) q.set('opportunityId', opportunityId);
  if (entry) q.set('entry', entry);
  const qs = q.toString();
  return qs ? `${base}?${qs}` : base;
}

function buildGoalWorkspaceHref(planId) {
  const id = opaque(planId);
  if (!id) return '/ora';
  return `/goal-workspace/${id}`;
}

/** True if href is the DEV AI harness (must not be used by production nav). */
function isDevOraAiHref(href) {
  return href === '/ora-ai' || href.startsWith('/ora-ai/');
}

function assertNoSensitiveQuery(href) {
  const lower = href.toLowerCase();
  const banned = ['name=', 'job=', 'exam=', 'location=', 'email=', 'phone='];
  return !banned.some((b) => lower.includes(b));
}
